config.script:
// estoque_avisos — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Agendado (padrão: dia útil às 8h, fuso da clínica — a clínica muda em "Quando roda"):
//   1. lista os alertas do estoque que a equipe ainda NÃO recebeu (listar_alertas);
//   2. guarda só os tipos ligados em `config.tipos`; sem nada, sai limpo;
//   3. manda UM resumo por papel de `config.papeis_destino` (ou para todos os conectados, com
//      `config.avisar_todos`): contagem por severidade/tipo + as primeiras linhas (produto, local,
//      lote/validade ou remessa/prazo, quantidade/mínimo). Os alertas não trazem dado de paciente;
//   4. SÓ se o aviso chegou a todos os destinos, marca as chaves como avisadas (marcar_avisados, até
//      500 por chamada). Aviso que falha NÃO marca: na próxima rodada o alerta volta.
//
// Falha visível: listar ou avisar que falha sai com log WARNING e `acao_bloqueada` no resumo.
// O resumo (result) só leva contagens e flags.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var TIPOS = ['validade_vencida', 'validade_proxima', 'abaixo_minimo', 'consignado_prazo_vencido', 'consignado_prazo_proximo'];
var ROTULO = {
  validade_vencida: ['lote vencido', 'lotes vencidos'],
  validade_proxima: ['lote perto de vencer', 'lotes perto de vencer'],
  abaixo_minimo: ['item abaixo do mínimo', 'itens abaixo do mínimo'],
  consignado_prazo_vencido: ['remessa consignada com prazo vencido', 'remessas consignadas com prazo vencido'],
  consignado_prazo_proximo: ['remessa consignada perto do prazo', 'remessas consignadas perto do prazo']
};
var LOTE_MARCAR = 500;

function num(v, d) { return (v !== undefined && v !== null && v !== '' && !isNaN(Number(v))) ? Number(v) : d; }
function ligado(v) { return !(v === false || v === 'false' || v === 0 || v === '0'); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}

// config.tipos: objeto {tipo: bool} (padrão do manifesto), lista de tipos ou texto "a,b". Ausente = todos.
function tiposLigados(t) {
  var on = {};
  var i;
  if (t === undefined || t === null || t === '') { for (i = 0; i < TIPOS.length; i++) on[TIPOS[i]] = true; return on; }
  if (typeof t === 'string') t = t.split(',');
  if (Array.isArray(t)) {
    for (i = 0; i < t.length; i++) { var k = String(t[i]).trim(); if (k) on[k] = true; }
    return on;
  }
  for (i = 0; i < TIPOS.length; i++) on[TIPOS[i]] = (t[TIPOS[i]] === undefined) ? true : ligado(t[TIPOS[i]]);
  return on;
}
// config.papeis_destino: "administrador,estoque" (o campo de papéis da Central) ou lista.
function papeisDe(v) {
  var lista = Array.isArray(v) ? v : String(v || '').split(',');
  var out = [];
  for (var i = 0; i < lista.length; i++) {
    var p = String(lista[i]).trim();
    if (p && out.indexOf(p) < 0) out.push(p);
  }
  return out;
}

function qtd(v) {
  var n = Number(v);
  if (v === null || v === undefined || isNaN(n)) return '?';
  return String(Math.round(n * 100) / 100).replace('.', ',');
}
function dataBr(iso) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  return m ? (m[3] + '/' + m[2] + '/' + m[1]) : '';
}
function quando(dias, verboFuturo, verboPassado) {
  if (dias === null || dias === undefined || isNaN(Number(dias))) return '';
  var d = Number(dias);
  if (d < 0) return verboPassado + ' há ' + (-d) + (d === -1 ? ' dia' : ' dias');
  if (d === 0) return verboFuturo + ' hoje';
  return verboFuturo + ' em ' + d + (d === 1 ? ' dia' : ' dias');
}
function corta(s, n) { s = String(s || ''); return s.length > n ? s.substring(0, n - 1) + '…' : s; }

function linha(a) {
  var t = a.tipo;
  var prod = a.produto_nome || 'Produto sem nome';
  var local = a.local_nome ? (' · ' + a.local_nome) : '';
  if (t === 'validade_vencida' || t === 'validade_proxima') {
    var lote = a.lote_numero ? (' · lote ' + a.lote_numero) : '';
    var val = dataBr(a.lote_validade);
    var q = quando(a.dias_restantes, 'vence', 'venceu');
    return (t === 'validade_vencida' ? 'Vencido: ' : 'Vence logo: ') + prod + local + lote +
      (val ? ' · validade ' + val : '') + (q ? ' (' + q + ')' : '') + ' · ' + qtd(a.quantidade) + ' no local';
  }
  if (t === 'abaixo_minimo') {
    return (a.severidade === 'critico' ? 'Sem saldo: ' : 'Abaixo do mínimo: ') + prod + local +
      ' · ' + qtd(a.quantidade) + ' de mínimo ' + qtd(a.minimo);
  }
  // consignado: a remessa tem vários itens, então não há produto
  var rem = 'Remessa' + (a.nf_numero ? ' NF ' + a.nf_numero : '') + (a.fornecedor_nome ? ' (' + a.fornecedor_nome + ')' : '');
  var prazo = dataBr(a.prazo_ate);
  var q2 = quando(a.dias_restantes, 'vence', 'venceu');
  return (t === 'consignado_prazo_vencido' ? 'Consignado vencido: ' : 'Consignado perto do prazo: ') + rem +
    (prazo ? ' · prazo ' + prazo : '') + (q2 ? ' (' + q2 + ')' : '') + ' · ' + qtd(a.quantidade) + ' em saldo';
}
function plural(n, par) { return n + ' ' + (n === 1 ? par[0] : par[1]); }

var on = tiposLigados(cfg.tipos);
var papeis = papeisDe(cfg.papeis_destino);
var avisarTodos = cfg.avisar_todos === true || cfg.avisar_todos === 'true';
var maxLinhas = Math.max(0, Math.min(num(cfg.max_linhas, 10), 30));
var link = cfg.link || '/financeiro/estoque';
var resumo = { alertas: 0, avisados: 0, marcados: 0, ignorados: 0, destinos: 0, falhas_aviso: 0 };

// ---- 1) alertas ainda não avisados ----
var r = call('listar_alertas', {});
var corpo = unwrap(r);
if (!corpo || !Array.isArray(corpo.itens)) {
  var http = (r && r.status_code) || null;
  log('estoque_avisos: FALHA ao listar os alertas (HTTP ' + (http || '?') + ')', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'listar_alertas'; resumo.http = http;
  if (r && r.ok) resumo.erro = 'formato_inesperado';
  result(resumo);
  return { ok: false, erro: 'listar_falhou', http: http };
}

// ---- 2) só os tipos ligados ----
var itens = [];
for (var i = 0; i < corpo.itens.length; i++) {
  var a = corpo.itens[i];
  if (a && a.chave && on[a.tipo]) itens.push(a);
}
// Contagem: `por_tipo` conta tudo, mesmo com a lista truncada (teto de 1000).
var conta = {};
var total = 0;
for (var t = 0; t < TIPOS.length; t++) {
  var tp = TIPOS[t];
  if (!on[tp]) continue;
  var n = (corpo.por_tipo && corpo.por_tipo[tp] !== undefined) ? num(corpo.por_tipo[tp], 0) : 0;
  if (!corpo.por_tipo) { n = 0; for (var j = 0; j < itens.length; j++) if (itens[j].tipo === tp) n++; }
  if (n) { conta[tp] = n; total += n; }
}
resumo.alertas = total;
resumo.na_lista = itens.length;
resumo.por_tipo = conta;
if (corpo.truncado) resumo.truncado = true;
if (!itens.length) {
  log('estoque_avisos: nenhum alerta novo');
  result(resumo);
  return { ok: true, alertas: 0 };
}

if (!avisarTodos && !papeis.length) {
  log('estoque_avisos: nenhum papel em papeis_destino — ninguém foi avisado', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'papeis_destino'; resumo.erro = 'sem_destino';
  result(resumo);
  return { ok: false, erro: 'sem_destino' };
}

// ---- 3) um resumo: críticos primeiro (a lista já vem na ordem: crítico, dias, produto) ----
var criticos = [], avisos = [];
var CRIT = { validade_vencida: 1, consignado_prazo_vencido: 1 };
for (var c = 0; c < TIPOS.length; c++) {
  var tc = TIPOS[c];
  if (!conta[tc]) continue;
  if (tc === 'abaixo_minimo') {
    var zerados = 0;
    for (var z = 0; z < itens.length; z++) if (itens[z].tipo === 'abaixo_minimo' && itens[z].severidade === 'critico') zerados++;
    if (zerados) criticos.push(plural(zerados, ['item sem saldo (com mínimo)', 'itens sem saldo (com mínimo)']));
    var resto = conta[tc] - zerados;
    if (resto > 0) avisos.push(plural(resto, ROTULO[tc]));
  } else if (CRIT[tc]) criticos.push(plural(conta[tc], ROTULO[tc]));
  else avisos.push(plural(conta[tc], ROTULO[tc]));
}
var partes = [];
if (criticos.length) partes.push('Urgente: ' + criticos.join(', ') + '.');
if (avisos.length) partes.push('Atenção: ' + avisos.join(', ') + '.');
var detalhe = [];
for (var d = 0; d < itens.length && d < maxLinhas; d++) detalhe.push('• ' + corta(linha(itens[d]), 160));
var faltam = total - detalhe.length;
if (detalhe.length && faltam > 0) detalhe.push('… e mais ' + faltam + ' no painel de alertas do estoque.');
var texto = partes.join('\n') + (detalhe.length ? '\n' + detalhe.join('\n') : '');
var titulo = 'Estoque: ' + (total === 1 ? '1 alerta novo' : total + ' alertas novos');
var message = {
  type: criticos.length ? 'urgent' : 'alert', title: titulo, text: texto, icon: 'warning',
  links: [{ url: link, text: 'Abrir o estoque' }],
  windowsalert: cfg.notificacao_do_sistema === false || cfg.notificacao_do_sistema === 'false'
    ? null : { text: titulo + ': ' + partes.join(' '), url: link }
};

var destinos = [];
if (avisarTodos) destinos.push({ acao: 'notificar', corpo: { type: 'mensagem', message: message } });
else for (var p = 0; p < papeis.length; p++) destinos.push({ acao: 'notificar_grupo', papel: papeis[p], corpo: { type: 'mensagem', group_id: papeis[p], message: message } });
resumo.destinos = destinos.length;
var falhou = [];
for (var k = 0; k < destinos.length; k++) {
  var rn = call(destinos[k].acao, destinos[k].corpo);
  if (rn && rn.ok) resumo.avisados++;
  else {
    falhou.push({ destino: destinos[k].papel || 'todos', http: (rn && rn.status_code) || null });
    log('estoque_avisos: FALHA ao avisar ' + (destinos[k].papel || 'todos') + ' (HTTP ' + ((rn && rn.status_code) || '?') + ')', 'warning');
  }
}
if (falhou.length) {
  // Não marca: na próxima rodada os alertas voltam e o aviso é tentado de novo.
  resumo.falhas_aviso = falhou.length;
  resumo.acao_bloqueada = true; resumo.etapa = 'notificar'; resumo.falhas_detalhe = falhou.slice(0, 10);
  result(resumo);
  return { ok: false, erro: 'aviso_falhou', alertas: total };
}

// ---- 4) marca o que foi avisado (só o que estava na lista; o resto volta na próxima rodada) ----
var chaves = [];
for (var q = 0; q < itens.length; q++) chaves.push(String(itens[q].chave));
for (var o = 0; o < chaves.length; o += LOTE_MARCAR) {
  var rm = call('marcar_avisados', { chaves: chaves.slice(o, o + LOTE_MARCAR) });
  var bm = unwrap(rm);
  if (!rm || !rm.ok || !bm) {
    log('estoque_avisos: FALHA ao marcar avisados (HTTP ' + ((rm && rm.status_code) || '?') + ') — pode repetir o aviso', 'warning');
    resumo.acao_bloqueada = true; resumo.etapa = 'marcar_avisados'; resumo.http = (rm && rm.status_code) || null;
    break;
  }
  resumo.marcados += num(bm.marcados, 0);
  resumo.ignorados += (bm.ignorados && bm.ignorados.length) || 0;
}
log('estoque_avisos: ' + total + ' alerta(s) avisado(s) a ' + destinos.length + ' destino(s), ' + resumo.marcados + ' marcado(s)',
  resumo.acao_bloqueada ? 'warning' : 'info');
result(resumo);
return { ok: !resumo.acao_bloqueada, alertas: total, marcados: resumo.marcados };

// estoque_reposicao — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Agendado (padrão: dia útil às 7h30, fuso da clínica — knob `cron_reposicao` ou "Quando roda"):
//   1. lista os alertas "abaixo do mínimo" que ainda NÃO têm tarefa de reposição (listar_sem_tarefa);
//   2. para cada produto × local abre UMA tarefa (criar_tarefa) para o papel de `config.papel_reposicao`
//      (tarefa do grupo): "Repor <produto> em <local>", físico × mínimo e o link para o produto;
//   3. logo depois que a tarefa nasce, marca o alerta no canal `tarefa` (marcar_com_tarefa). A marca cai
//      sozinha quando a condição some (o saldo voltou acima do mínimo) — a próxima queda abre outra tarefa.
//
// Sem chave de idempotência na tarefa: se a tarefa nascer e a marca falhar, a próxima rodada pode abrir
// outra (duplicata eventual ACEITA — decisão do dono). A falha da marca vai para o log e `acao_bloqueada`.
// Falha ao listar (inclusive 409) ou ao criar: log WARNING + `acao_bloqueada`, sem marcar.
// O resumo (result) só leva contagens e flags — sem nome de produto, sem dado pessoal.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var LIMITE_TITULO = 200;

function num(v, d) { return (v !== undefined && v !== null && v !== '' && !isNaN(Number(v))) ? Number(v) : d; }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function qtd(v) {
  var n = Number(v);
  if (v === null || v === undefined || v === '' || isNaN(n)) return '?';
  return String(Math.round(n * 100) / 100).replace('.', ',');
}
function corta(s, n) { s = String(s || ''); return s.length > n ? s.substring(0, n - 1) + '…' : s; }

var papel = String(cfg.papel_reposicao || '').split(',')[0].trim();
var link = String(cfg.link || '/financeiro/estoque');
var maxPorRodada = Math.max(1, Math.min(num(cfg.max_por_rodada, 50), 200));
var resumo = { alertas: 0, tarefas: 0, marcados: 0, falhas_tarefa: 0, falhas_marca: 0 };

if (!papel) {
  log('estoque_reposicao: papel_reposicao vazio — nenhuma tarefa aberta', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'papel_reposicao'; resumo.erro = 'sem_responsavel';
  result(resumo);
  return { ok: false, erro: 'sem_responsavel' };
}

// ---- 1) alertas abaixo do mínimo ainda sem tarefa ----
var r = call('listar_sem_tarefa', {});
var corpo = unwrap(r);
if (!corpo || !Array.isArray(corpo.itens)) {
  var http = (r && r.status_code) || null;
  log('estoque_reposicao: FALHA ao listar os alertas sem tarefa (HTTP ' + (http || '?') + ')', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'listar_sem_tarefa'; resumo.http = http;
  if (r && r.ok) resumo.erro = 'formato_inesperado';
  result(resumo);
  return { ok: false, erro: 'listar_falhou', http: http };
}

// Uma tarefa por produto × local (a chave do alerta já é por produto × local; deduplica por garantia).
var itens = [];
var vistos = {};
for (var i = 0; i < corpo.itens.length; i++) {
  var a = corpo.itens[i];
  if (!a || a.tipo !== 'abaixo_minimo' || !a.chave) continue;
  var k = String(a.produto_id || '') + '|' + String(a.local_id || '') + '|' + String(a.chave);
  if (vistos[k]) continue;
  vistos[k] = true;
  itens.push(a);
}
resumo.alertas = itens.length;
if (corpo.truncado) resumo.truncado = true;
if (!itens.length) {
  log('estoque_reposicao: nenhum item abaixo do mínimo sem tarefa');
  result(resumo);
  return { ok: true, tarefas: 0 };
}
if (itens.length > maxPorRodada) { resumo.adiados = itens.length - maxPorRodada; itens = itens.slice(0, maxPorRodada); }

// ---- 2) e 3) uma tarefa por item, marcada logo em seguida ----
var falhas = [];
for (var j = 0; j < itens.length; j++) {
  var it = itens[j];
  var prod = it.produto_nome || 'produto sem nome';
  var local = it.local_nome || 'local sem nome';
  var titulo = corta('Repor ' + prod + ' em ' + local, LIMITE_TITULO);
  var url = link + (it.produto_id ? ((link.indexOf('?') >= 0 ? '&' : '?') + 'item=' + encodeURIComponent(String(it.produto_id))) : '');
  var descricao = (it.severidade === 'critico' ? 'Sem saldo neste local. ' : 'Abaixo do mínimo deste local. ') +
    'Físico: ' + qtd(it.quantidade) + ' · mínimo: ' + qtd(it.minimo) +
    (it.produto_codigo ? ' · código ' + it.produto_codigo : '') + '.\n' +
    'Abrir o produto no estoque: ' + url + '\n' +
    'Tarefa aberta pelo agente de reposição do estoque. Se o saldo voltar acima do mínimo, a próxima queda abre outra tarefa.';

  var rt = call('criar_tarefa', {
    titulo: titulo,
    descricao: descricao,
    prioridade: it.severidade === 'critico' ? 'alta' : 'media',
    responsavel_tipo: 'role',
    responsavel_id: papel
  });
  if (!rt || !rt.ok) {
    resumo.falhas_tarefa++;
    falhas.push({ etapa: 'criar_tarefa', http: (rt && rt.status_code) || null });
    log('estoque_reposicao: FALHA ao abrir a tarefa (HTTP ' + ((rt && rt.status_code) || '?') + ') — o alerta volta na próxima rodada', 'warning');
    continue;
  }
  resumo.tarefas++;

  var rm = call('marcar_com_tarefa', { chaves: [String(it.chave)], canal: 'tarefa' });
  var bm = unwrap(rm);
  if (!rm || !rm.ok || !bm) {
    resumo.falhas_marca++;
    falhas.push({ etapa: 'marcar_com_tarefa', http: (rm && rm.status_code) || null });
    log('estoque_reposicao: tarefa aberta mas a marca FALHOU (HTTP ' + ((rm && rm.status_code) || '?') +
      ') — a próxima rodada pode abrir outra tarefa para o mesmo item', 'warning');
    continue;
  }
  resumo.marcados += num(bm.marcados, 0);
}

if (falhas.length) {
  resumo.acao_bloqueada = true;
  resumo.etapa = resumo.falhas_marca ? 'marcar_com_tarefa' : 'criar_tarefa';
  resumo.falhas_detalhe = falhas.slice(0, 10);
}
log('estoque_reposicao: ' + resumo.tarefas + ' tarefa(s) aberta(s), ' + resumo.marcados + ' marcada(s) de ' + resumo.alertas + ' alerta(s)',
  resumo.acao_bloqueada ? 'warning' : 'info');
result(resumo);
return { ok: !resumo.acao_bloqueada, tarefas: resumo.tarefas, marcados: resumo.marcados };

// estoque_relatorio_fornecedor — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Agendado (padrão: segunda às 9h, fuso da clínica — knob `cron_relatorio` ou "Quando roda"):
//   1. lista o consumo de material consignado que AINDA AGUARDA reposição nos últimos `dias_janela` dias
//      (consumo_aguardando, sempre em JSON). Consignado desligado (409) = saída limpa;
//   2. agrupa por fornecedor. Um lembrete que repete toda semana até alguém marcar "reposto";
//   3. por fornecedor:
//      - alguma linha com `paciente_incompleto` (o cadastro de pacientes estava fora do ar) → NÃO envia e
//        avisa a gestão (vai na próxima rodada). Identificação vazia por outro motivo sai como "—" e envia;
//      - busca o fornecedor (obter_fornecedor): sem e-mail ou não encontrado → NÃO envia e avisa a gestão;
//      - envia o e-mail (enviar_intencao) com o template `config.template_slug`, as linhas nas variáveis do
//        template e `idempotency_key` = estoque-relatorio:<fornecedor_id>:<semana ISO> (sem dado pessoal):
//        rodar de novo na mesma semana não manda outro e-mail;
//   4. um único aviso à gestão (`config.papel_gestao`) com os fornecedores que ficaram sem envio.
// Não marca "reposto" (é da equipe, ou da nota de faturamento do fornecedor).
//
// Minimização (LGPD art. 6º, III): a linha leva só a identificação que a clínica escolheu no estoque
// (padrão = nº do atendimento). Nada de diagnóstico, CID ou prontuário. O e-mail do fornecedor é usado
// só como destinatário — nunca vai para o log nem para o resumo.
// O resumo (result) só leva contagens e flags.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var DIA_MS = 86400000;

function num(v, d) { return (v !== undefined && v !== null && v !== '' && !isNaN(Number(v))) ? Number(v) : d; }
function ligado(v) { return !(v === false || v === 'false' || v === 0 || v === '0'); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }
function isoData(ms) { var d = new Date(ms); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
function dataBr(iso) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  return m ? (m[3] + '/' + m[2] + '/' + m[1]) : '';
}
function qtd(v) {
  var n = Number(v);
  if (v === null || v === undefined || v === '' || isNaN(n)) return '?';
  return String(Math.round(n * 1000) / 1000).replace('.', ',');
}
// Semana ISO 8601 (segunda a domingo) da data local `ms` (já deslocada para o fuso da clínica).
function semanaIso(ms) {
  var d = new Date(ms);
  var t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  var x = new Date(t);
  var dow = x.getUTCDay() || 7;
  x.setUTCDate(x.getUTCDate() + 4 - dow);
  var ano = x.getUTCFullYear();
  var sem = Math.ceil(((x.getTime() - Date.UTC(ano, 0, 1)) / DIA_MS + 1) / 7);
  return ano + '-W' + pad(sem);
}

var papelGestao = String(cfg.papel_gestao || '').split(',')[0].trim();
var dias = Math.max(1, Math.min(Math.floor(num(cfg.dias_janela, 90)), 366));
var template = String(cfg.template_slug || 'estoque_relatorio_fornecedor').trim();
var maxLinhas = Math.max(1, Math.min(num(cfg.max_linhas_email, 300), 1000));
var link = String(cfg.link || '/financeiro/estoque?aba=consignado');
// Fuso da clínica para "hoje" e para a semana ISO (São Paulo = -3, sem horário de verão).
var agoraLocal = Date.now() + num(cfg.fuso_horas, -3) * 3600000;
var ate = isoData(agoraLocal);
var desde = isoData(agoraLocal - dias * DIA_MS);
var semana = semanaIso(agoraLocal);
var resumo = { linhas: 0, fornecedores: 0, enviados: 0, deduplicados: 0, agendados: 0, sem_email: 0,
               nao_encontrado: 0, paciente_incompleto: 0, falhas_envio: 0, semana: semana, dias_janela: dias };

// ---- 1) consumo aguardando reposição ----
var r = call('consumo_aguardando', { desde: desde, ate: ate });
if (r && r.status_code === 409) {
  log('estoque_relatorio_fornecedor: consignado desligado na clínica — nada a enviar');
  resumo.consignado = 'desligado';
  result(resumo);
  return { ok: true, skip: 'consignado_desligado' };
}
var lista = unwrap(r);
if (!Array.isArray(lista)) {
  var http = (r && r.status_code) || null;
  log('estoque_relatorio_fornecedor: FALHA ao listar o consumo do consignado (HTTP ' + (http || '?') + ')', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'consumo_aguardando'; resumo.http = http;
  if (r && r.ok) resumo.erro = 'formato_inesperado';
  result(resumo);
  return { ok: false, erro: 'listar_falhou', http: http };
}

// ---- 2) agrupa por fornecedor ----
var grupos = {};
var ordem = [];
for (var i = 0; i < lista.length; i++) {
  var l = lista[i];
  if (!l || !l.fornecedor_id || (l.reposicao && l.reposicao !== 'aguardando')) continue;
  var fid = String(l.fornecedor_id);
  if (!grupos[fid]) { grupos[fid] = { id: fid, nome: l.fornecedor_nome || 'Fornecedor', linhas: [], incompleto: false }; ordem.push(fid); }
  grupos[fid].linhas.push(l);
  if (l.paciente_incompleto === true) grupos[fid].incompleto = true;
  resumo.linhas++;
}
resumo.fornecedores = ordem.length;
if (!ordem.length) {
  log('estoque_relatorio_fornecedor: nada aguardando reposição na janela');
  result(resumo);
  return { ok: true, fornecedores: 0 };
}

function variaveisDe(g, nomeFornecedor) {
  var linhas = [];
  var total = 0;
  for (var j = 0; j < g.linhas.length; j++) {
    var x = g.linhas[j];
    total += num(x.quantidade, 0);
    if (linhas.length >= maxLinhas) continue;
    linhas.push({
      data: dataBr(x.data),
      produto: x.produto_nome || 'Produto sem nome',
      codigo: x.produto_codigo || '',
      lote: x.lote_numero || '',
      validade: dataBr(x.lote_validade),
      serie: x.numero_serie || '',
      quantidade: qtd(x.quantidade),
      remessa_nf: x.remessa_nf || '',
      paciente: (x.paciente === null || x.paciente === undefined || x.paciente === '') ? '—' : String(x.paciente)
    });
  }
  return {
    fornecedor_nome: nomeFornecedor,
    periodo_desde: dataBr(desde),
    periodo_ate: dataBr(ate),
    semana: semana,
    total_linhas: g.linhas.length,
    total_quantidade: qtd(total),
    linhas_omitidas: Math.max(0, g.linhas.length - linhas.length),
    linhas: linhas
  };
}

// ---- 3) por fornecedor ----
var pendencias = [];   // {fornecedor, motivo} para a gestão (nome do fornecedor: empresa, não paciente)
var falhas = [];
for (var f = 0; f < ordem.length; f++) {
  var g = grupos[ordem[f]];
  if (g.incompleto) {
    resumo.paciente_incompleto++;
    pendencias.push({ fornecedor: g.nome, motivo: 'a identificação do paciente não pôde ser lida (cadastro de pacientes fora do ar) — vai na próxima rodada' });
    continue;
  }
  var rf = call('obter_fornecedor', { id: g.id });
  if (rf && rf.status_code === 404) {
    resumo.nao_encontrado++;
    pendencias.push({ fornecedor: g.nome, motivo: 'fornecedor não encontrado no cadastro do financeiro' });
    continue;
  }
  var forn = unwrap(rf);
  if (!forn) {
    resumo.falhas_envio++;
    falhas.push({ etapa: 'obter_fornecedor', http: (rf && rf.status_code) || null });
    log('estoque_relatorio_fornecedor: FALHA ao ler o fornecedor (HTTP ' + ((rf && rf.status_code) || '?') + ')', 'warning');
    continue;
  }
  var email = String(forn.email || '').trim();
  if (!email || email.indexOf('@') < 1) {
    resumo.sem_email++;
    pendencias.push({ fornecedor: forn.nome || g.nome, motivo: 'sem e-mail no cadastro do fornecedor' });
    continue;
  }
  var re = call('enviar_intencao', {
    destinatario_email: email,
    modo_entrega: 'force_channel',
    canal_solicitado: 'email',
    template_slug: template,
    variaveis: variaveisDe(g, forn.nome || g.nome),
    origem_ms: 'agentes',
    referencia_tipo: 'estoque_consignado_fornecedor',
    idempotency_key: 'estoque-relatorio:' + g.id + ':' + semana
  });
  var be = unwrap(re);
  var st = be && be.status;
  if (re && re.ok && st === 'aceito') resumo.enviados++;
  else if (re && re.ok && st === 'deduplicado') resumo.deduplicados++;
  else if (re && re.ok && st === 'agendado') resumo.agendados++;
  else {
    resumo.falhas_envio++;
    falhas.push({ etapa: 'enviar_intencao', http: (re && re.status_code) || null, status: st || null });
    log('estoque_relatorio_fornecedor: FALHA ao enviar o relatório (HTTP ' + ((re && re.status_code) || '?') +
      (st ? ', ' + st : '') + ')', 'warning');
  }
}

// ---- 4) um aviso à gestão com o que ficou sem envio ----
if (pendencias.length) {
  if (!papelGestao) {
    log('estoque_relatorio_fornecedor: ' + pendencias.length + ' fornecedor(es) sem envio e papel_gestao vazio — ninguém foi avisado', 'warning');
    falhas.push({ etapa: 'papel_gestao', erro: 'sem_destino' });
  } else {
    var linhasAviso = [];
    for (var p = 0; p < pendencias.length && p < 20; p++) linhasAviso.push('• ' + pendencias[p].fornecedor + ': ' + pendencias[p].motivo);
    if (pendencias.length > 20) linhasAviso.push('… e mais ' + (pendencias.length - 20) + '.');
    var titulo = 'Consignado: ' + (pendencias.length === 1 ? '1 relatório não enviado ao fornecedor' : pendencias.length + ' relatórios não enviados aos fornecedores');
    var message = {
      type: 'alert', title: titulo, icon: 'warning',
      text: 'O relatório semanal do que foi usado e aguarda reposição não foi enviado:\n' + linhasAviso.join('\n') +
        '\nCorrija o cadastro do fornecedor (e-mail) no financeiro; o envio é tentado de novo na próxima rodada.',
      links: [{ url: link, text: 'Abrir o consignado' }],
      windowsalert: ligado(cfg.notificacao_do_sistema) ? { text: titulo, url: link } : null
    };
    var rn = call('notificar_grupo', { type: 'mensagem', group_id: papelGestao, message: message });
    if (rn && rn.ok) resumo.gestao_avisada = true;
    else {
      falhas.push({ etapa: 'notificar_grupo', http: (rn && rn.status_code) || null });
      log('estoque_relatorio_fornecedor: FALHA ao avisar a gestão (HTTP ' + ((rn && rn.status_code) || '?') + ')', 'warning');
    }
  }
  resumo.sem_envio = pendencias.length;
}

if (falhas.length) {
  resumo.acao_bloqueada = true;
  resumo.etapa = falhas[0].etapa;
  resumo.falhas_detalhe = falhas.slice(0, 10);
}
log('estoque_relatorio_fornecedor: ' + resumo.fornecedores + ' fornecedor(es), ' + resumo.enviados + ' enviado(s), ' +
  resumo.deduplicados + ' já enviado(s) na semana, ' + (resumo.sem_envio || 0) + ' sem envio',
  resumo.acao_bloqueada ? 'warning' : 'info');
result(resumo);
return { ok: !resumo.acao_bloqueada, enviados: resumo.enviados, sem_envio: resumo.sem_envio || 0 };
